-- ADR-0036: service runs are labelled and kept out of people counts (migration 012).

CREATE OR REPLACE VIEW cardo.silver_session (`session_id` String, `pseudonym` Nullable(String), `salt_version` String, `cohort` String, `app_version` String, `terminal_type` String, `start_type` String, `started_at` DateTime64(9), `last_event_at` DateTime64(9), `day` Date, `clock` String, `ended` UInt8, `end_reason` String, `has_otel` UInt8, `has_hooks` UInt8, `actor_kind` String, `workflow` String) AS SELECT session_id, nullIf(anyIf(e_pseudonym, e_pseudonym != ''), '') AS pseudonym, anyIf(e_salt_version, (e_salt_version != '') AND (e_clock != 'collector')) AS salt_version, anyIf(e_cohort, e_cohort != '') AS cohort, anyIf(e_app_version, e_app_version != '') AS app_version, anyIf(e_terminal_type, e_terminal_type != '') AS terminal_type, anyIf(e_start_type, e_start_type != '') AS start_type, multiIf(countIf(e_clock = 'client') > 0, minIf(e_ts, e_clock = 'client'), countIf(e_clock = 'collector') > 0, minIf(e_ts, e_clock = 'collector'), min(e_ts)) AS started_at, multiIf(countIf(e_clock = 'client') > 0, maxIf(e_ts, e_clock = 'client'), countIf(e_clock = 'collector') > 0, maxIf(e_ts, e_clock = 'collector'), max(e_ts)) AS last_event_at, toDate(started_at) AS day, if(countIf(e_clock = 'client') > 0, 'client', 'collector') AS clock, countIf(e_event = 'SessionEnd') > 0 AS ended, anyIf(e_end_reason, e_end_reason != '') AS end_reason, countIf(e_clock = 'client') > 0 AS has_otel, countIf(e_clock = 'collector') > 0 AS has_hooks, if(anyIf(svc_kind, svc_kind != '') = 'service', 'service', 'person') AS actor_kind, anyIf(svc_workflow, svc_workflow != '') AS workflow FROM (SELECT LogAttributes['session.id'] AS session_id, if((LogAttributes['user.pseudonym']) != '', LogAttributes['user.pseudonym'], ResourceAttributes['user.pseudonym']) AS e_pseudonym, ResourceAttributes['cardo.salt_version'] AS e_salt_version, if((ResourceAttributes['cardo.cohort']) != '', ResourceAttributes['cardo.cohort'], LogAttributes['cardo.cohort']) AS e_cohort, LogAttributes['app.version'] AS e_app_version, LogAttributes['terminal.type'] AS e_terminal_type, '' AS e_start_type, Timestamp AS e_ts, 'client' AS e_clock, EventName AS e_event, '' AS e_end_reason FROM cardo.bronze_otel_logs WHERE (LogAttributes['session.id']) != '' UNION ALL SELECT Attributes['session.id'], if((Attributes['user.pseudonym']) != '', Attributes['user.pseudonym'], ResourceAttributes['user.pseudonym']), ResourceAttributes['cardo.salt_version'], if((ResourceAttributes['cardo.cohort']) != '', ResourceAttributes['cardo.cohort'], Attributes['cardo.cohort']), Attributes['app.version'], Attributes['terminal.type'], Attributes['start_type'], toDateTime64(TimeUnix, 9), 'metric', MetricName, '' FROM cardo.bronze_otel_metrics_sum WHERE (MetricName = 'claude_code.session.count') AND ((Attributes['session.id']) != '') UNION ALL SELECT LogAttributes['session_id'], '', ResourceAttributes['cardo.salt_version'], '', '', '', '', Timestamp, 'collector', EventName, LogAttributes['session_end_reason'] FROM cardo.bronze_hook_events WHERE (LogAttributes['session_id']) != '') AS b LEFT JOIN (SELECT LogAttributes['session.id'] AS session_id, 'service' AS svc_kind, any(ResourceAttributes['cardo.workflow']) AS svc_workflow FROM cardo.bronze_otel_logs WHERE ResourceAttributes['cardo.actor'] = 'service' AND LogAttributes['session.id'] != '' GROUP BY session_id) AS svc USING (session_id) GROUP BY session_id;

CREATE OR REPLACE VIEW cardo.gold_fleet_adoption (`day` Date, `source` LowCardinality(String), `active_actors` UInt64, `sessions` Int64, `lines_added` Int64, `lines_removed` Int64, `commits` Int64, `pull_requests` Int64, `sessions_per_active_actor` Nullable(Float64)) AS WITH totals AS (SELECT day, source, countDistinctIf(pseudonym, pseudonym != '') AS active_actors, sum(sessions) AS sessions_total, sum(lines_added) AS lines_added_total, sum(lines_removed) AS lines_removed_total, sum(commits) AS commits_total, sum(pull_requests) AS pull_requests_total FROM cardo.silver_actor_day GROUP BY day, source) SELECT day, source, active_actors, sessions_total AS sessions, lines_added_total AS lines_added, lines_removed_total AS lines_removed, commits_total AS commits, pull_requests_total AS pull_requests, round(sessions_total / nullIf(active_actors, 0), 2) AS sessions_per_active_actor FROM totals ORDER BY day ASC;

CREATE OR REPLACE VIEW cardo.gold_artifact_usage (`week` Date, `kind` String, `artifact` String, `file_kind` String, `is_org` Nullable(UInt8), `is_builtin` UInt8, `people` UInt64, `sessions` UInt64, `uses` UInt64, `active_people` UInt64, `people_share` Nullable(Float64)) AS WITH (SELECT min_group_size FROM cardo.settings_effective) AS min_group, fleet AS (SELECT toMonday(day) AS week, countDistinct(pseudonym) AS active_people FROM cardo.silver_session WHERE actor_kind != 'service' GROUP BY week), per_name AS (SELECT toMonday(day) AS week, kind, name, countDistinct(pseudonym) AS name_people FROM cardo.silver_artifact_load WHERE session_id IN (SELECT session_id FROM cardo.silver_session WHERE actor_kind != 'service') GROUP BY week, kind, name), usage AS (SELECT toMonday(a.day) AS week, a.kind AS kind, if(a.is_org OR a.is_builtin OR (a.name = '') OR (n.name_people >= min_group), a.name, 'other') AS artifact, a.file_kind AS file_kind, a.is_org AS org, a.is_builtin AS builtin, countDistinct(pseudonym) AS people_total, countDistinct(a.session_id) AS sessions_total, count() AS uses_total FROM cardo.silver_artifact_load AS a INNER JOIN per_name AS n ON (n.week = toMonday(a.day)) AND (n.kind = a.kind) AND (n.name = a.name) WHERE a.session_id IN (SELECT session_id FROM cardo.silver_session WHERE actor_kind != 'service') GROUP BY week, kind, artifact, file_kind, org, builtin) SELECT u.week AS week, u.kind AS kind, u.artifact AS artifact, u.file_kind AS file_kind, u.org AS is_org, u.builtin AS is_builtin, u.people_total AS people, u.sessions_total AS sessions, u.uses_total AS uses, f.active_people AS active_people, round(u.people_total / nullIf(f.active_people, 0), 4) AS people_share FROM usage AS u LEFT JOIN fleet AS f ON f.week = u.week ORDER BY week ASC, kind ASC, people DESC;
